artifacts.solve_py:
import os
import csv
import json

from pyscipopt import Model, quicksum

DATA = "/app/data"
OUT = "/app/submissions/solution.csv"


def read_csv(name):
    with open(os.path.join(DATA, name), newline="") as f:
        return list(csv.DictReader(f))


def main():
    with open(os.path.join(DATA, "config.json")) as f:
        cfg = json.load(f)
    carbon_price = float(cfg["carbon_price_per_kg"])
    carbon_cap = float(cfg["carbon_cap_kg"])
    tol = float(cfg["feasibility_tolerance"])

    markets = read_csv("markets.csv")
    hubs = read_csv("collection_hubs.csv")
    tests = read_csv("testing_centers.csv")
    outlets = read_csv("outlets.csv")
    policy = read_csv("policy_rules.csv")
    lanes = read_csv("lanes.csv")

    M = [r["market_id"] for r in markets]
    C = ["lfp", "nmc"]
    H = [r["hub_id"] for r in hubs]
    T = [r["test_id"] for r in tests]
    O = [r["outlet_id"] for r in outlets]

    mkt = {r["market_id"]: r for r in markets}
    hub = {r["hub_id"]: r for r in hubs}
    tst = {r["test_id"]: r for r in tests}
    out = {r["outlet_id"]: r for r in outlets}
    pol = {r["chemistry"]: r for r in policy}

    V = {(m, c): float(mkt[m][c + "_packs"]) for m in M for c in C}
    Dmg = {(m, c): float(mkt[m]["damaged_" + c + "_share"]) for m in M for c in C}
    Trace = {m: float(mkt[m]["traceability_score"]) for m in M}
    AudReq = {m: float(mkt[m]["min_audited_test_share"]) for m in M}

    fcH = {h: float(hub[h]["fixed_cost"]) for h in H}
    feH = {h: float(hub[h]["fixed_emission_kg"]) for h in H}
    capH = {h: float(hub[h]["capacity_packs"]) for h in H}
    minH = {h: float(hub[h]["min_throughput_if_open"]) for h in H}
    hcH = {h: float(hub[h]["handling_cost_per_pack"]) for h in H}
    heH = {h: float(hub[h]["handling_emission_kg_per_pack"]) for h in H}
    nmcH = {h: int(hub[h]["nmc_certified"]) for h in H}

    fcT = {t: float(tst[t]["fixed_cost"]) for t in T}
    feT = {t: float(tst[t]["fixed_emission_kg"]) for t in T}
    capT = {t: float(tst[t]["capacity_packs"]) for t in T}
    minT = {t: float(tst[t]["min_throughput_if_open"]) for t in T}
    tcT = {t: float(tst[t]["test_cost_per_pack"]) for t in T}
    teT = {t: float(tst[t]["test_emission_kg_per_pack"]) for t in T}
    auT = {t: int(tst[t]["audit_upgrade"]) for t in T}
    rcT = {t: int(tst[t]["reman_certified"]) for t in T}

    capO = {o: float(out[o]["capacity_packs"]) for o in O}
    pcO = {(o, c): float(out[o]["processing_cost_" + c]) for o in O for c in C}
    rvO = {(o, c): float(out[o]["recovered_value_" + c]) for o in O for c in C}
    peO = {(o, c): float(out[o]["processing_emission_" + c]) for o in O for c in C}
    elO = {(o, c): int(out[o][c + "_allowed"]) for o in O for c in C}

    R_set = {o for o in O if out[o]["outlet_type"] == "remanufacturing"}
    S_set = {o for o in O if out[o]["outlet_type"] == "second_life"}
    HYD_set = {o for o in O if out[o]["outlet_type"] == "recycler" and "hydro" in out[o]["technology"]}
    PYR_set = {o for o in O if out[o]["outlet_type"] == "recycler" and "pyro" in out[o]["technology"]}
    D_set = {o for o in O if out[o]["outlet_type"] == "disposal"}
    HV_set = R_set | S_set
    RC_set = HYD_set | PYR_set

    lane1 = {}
    lane2 = {}
    lane3 = {}
    for r in lanes:
        rec = {
            "dist": float(r["distance_km"]),
            "cap": float(r["capacity_packs"]),
            "cpk": float(r["cost_per_pack_km"]),
            "epk": float(r["emission_kg_per_pack_km"]),
            "lfp": int(r["lfp_allowed"]),
            "nmc": int(r["nmc_allowed"]),
        }
        if r["stage"] == "market_to_hub":
            lane1[(r["from_id"], r["to_id"])] = rec
        elif r["stage"] == "hub_to_test":
            lane2[(r["from_id"], r["to_id"])] = rec
        else:
            lane3[(r["from_id"], r["to_id"])] = rec

    # Eligibility predicates
    def x1_ok(m, c, h):
        L = lane1.get((m, h))
        return L is not None and L[c] == 1

    def x2_ok(m, c, h, t):
        L = lane2.get((h, t))
        if L is None or L[c] != 1:
            return False
        if c == "nmc" and nmcH[h] != 1:
            return False
        return True

    def x3_ok(m, c, t, o):
        L = lane3.get((t, o))
        if L is None or L[c] != 1:
            return False
        if elO[(o, c)] != 1:
            return False
        if o in R_set and rcT[t] != 1:
            return False
        if o in R_set and Trace[m] < 0.75 and auT[t] != 1:
            return False
        return True

    # Build variable key sets
    x1_keys = [(m, c, h) for m in M for c in C for h in H if x1_ok(m, c, h)]
    x2_keys = [(m, c, h, t) for m in M for c in C for h in H for t in T if x2_ok(m, c, h, t)]
    x3_keys = [(m, c, t, o) for m in M for c in C for t in T for o in O if x3_ok(m, c, t, o)]

    # For conservation: which x2 keys touch each (m,c,h); which x3 keys touch each (m,c,t)
    x2_from_mch = {}
    for k in x2_keys:
        m, c, h, t = k
        x2_from_mch.setdefault((m, c, h), []).append(k)
    x2_to_mct = {}
    x3_from_mct = {}
    for k in x2_keys:
        m, c, h, t = k
        x2_to_mct.setdefault((m, c, t), []).append(k)
    for k in x3_keys:
        m, c, t, o = k
        x3_from_mct.setdefault((m, c, t), []).append(k)

    model = Model("ev_battery_recycling_network")
    model.hideOutput()

    y = {}
    for h in H:
        y[h] = model.addVar(name="y_" + h, vtype="B", lb=0.0, ub=1.0, obj=fcH[h])
    z = {}
    for t in T:
        z[t] = model.addVar(name="z_" + t, vtype="B", lb=0.0, ub=1.0, obj=fcT[t])

    x1 = {}
    for k in x1_keys:
        m, c, h = k
        L = lane1[(m, h)]
        obj = L["dist"] * L["cpk"] + hcH[h] + carbon_price * (L["dist"] * L["epk"] + heH[h])
        x1[k] = model.addVar(name="x1_%s_%s_%s" % (m, c, h), vtype="C", lb=0.0, ub=V[(m, c)], obj=obj)

    x2 = {}
    for k in x2_keys:
        m, c, h, t = k
        L = lane2[(h, t)]
        obj = L["dist"] * L["cpk"] + tcT[t] + carbon_price * (L["dist"] * L["epk"] + teT[t])
        x2[k] = model.addVar(name="x2_%s_%s_%s_%s" % (m, c, h, t), vtype="C", lb=0.0, ub=V[(m, c)], obj=obj)

    x3 = {}
    for k in x3_keys:
        m, c, t, o = k
        L = lane3[(t, o)]
        obj = (L["dist"] * L["cpk"] + pcO[(o, c)] - rvO[(o, c)]
               + carbon_price * (L["dist"] * L["epk"] + peO[(o, c)]))
        x3[k] = model.addVar(name="x3_%s_%s_%s_%s" % (m, c, t, o), vtype="C", lb=0.0, ub=V[(m, c)], obj=obj)

    # Supply: exact routing of every market/chemistry
    for m in M:
        for c in C:
            keys = [k for k in x1_keys if k[0] == m and k[1] == c]
            model.addCons(quicksum(x1[k] for k in keys) == V[(m, c)],
                          name="supply_%s_%s" % (m, c))

    # Hub conservation: for every (m,c,h) that has any x1 variable
    for k in x1_keys:
        m, c, h = k
        out_keys = x2_from_mch.get((m, c, h), [])
        model.addCons(quicksum(x2[kk] for kk in out_keys) == x1[k],
                      name="hubcons_%s_%s_%s" % (m, c, h))

    # Test conservation: for every (m,c,t) that has any x2 or x3 variable
    mct_set = set(x2_to_mct.keys()) | set(x3_from_mct.keys())
    for (m, c, t) in mct_set:
        in_keys = x2_to_mct.get((m, c, t), [])
        out_keys = x3_from_mct.get((m, c, t), [])
        model.addCons(quicksum(x3[kk] for kk in out_keys) == quicksum(x2[kk] for kk in in_keys),
                      name="testcons_%s_%s_%s" % (m, c, t))

    # Hub capacity / min throughput
    for h in H:
        in_keys = [k for k in x1_keys if k[2] == h]
        if in_keys:
            model.addCons(quicksum(x1[k] for k in in_keys) <= capH[h] * y[h], name="hubcap_" + h)
            model.addCons(quicksum(x1[k] for k in in_keys) >= minH[h] * y[h], name="hubmin_" + h)

    # Test capacity / min throughput
    for t in T:
        in_keys = [k for k in x2_keys if k[3] == t]
        if in_keys:
            model.addCons(quicksum(x2[k] for k in in_keys) <= capT[t] * z[t], name="testcap_" + t)
            model.addCons(quicksum(x2[k] for k in in_keys) >= minT[t] * z[t], name="testmin_" + t)

    # Outlet capacity
    for o in O:
        keys = [k for k in x3_keys if k[3] == o]
        if keys:
            model.addCons(quicksum(x3[k] for k in keys) <= capO[o], name="outcap_" + o)

    # Lane capacity (all markets/chemistries on that lane)
    for (m, h), L in lane1.items():
        keys = [k for k in x1_keys if k[0] == m and k[2] == h]
        if keys:
            model.addCons(quicksum(x1[k] for k in keys) <= L["cap"], name="lane1_%s_%s" % (m, h))
    for (h, t), L in lane2.items():
        keys = [k for k in x2_keys if k[2] == h and k[3] == t]
        if keys:
            model.addCons(quicksum(x2[k] for k in keys) <= L["cap"], name="lane2_%s_%s" % (h, t))
    for (t, o), L in lane3.items():
        keys = [k for k in x3_keys if k[2] == t and k[3] == o]
        if keys:
            model.addCons(quicksum(x3[k] for k in keys) <= L["cap"], name="lane3_%s_%s" % (t, o))

    # Audited-testing share per market
    for m in M:
        total = sum(V[(m, c)] for c in C)
        if AudReq[m] > 0:
            keys = [k for k in x2_keys if k[0] == m and auT[k[3]] == 1]
            model.addCons(quicksum(x2[k] for k in keys) >= AudReq[m] * total, name="audit_" + m)

    # Damaged share cap on high-value channels
    for m in M:
        for c in C:
            keys = [k for k in x3_keys if k[0] == m and k[1] == c and k[3] in HV_set]
            if keys:
                model.addCons(quicksum(x3[k] for k in keys) <= (1.0 - Dmg[(m, c)]) * V[(m, c)],
                               name="dmg_%s_%s" % (m, c))

    # Policy rules per chemistry
    for c in C:
        total_c = sum(V[(m, c)] for m in M)
        p = pol[c]
        hv = [k for k in x3_keys if k[1] == c and k[3] in HV_set]
        sl = [k for k in x3_keys if k[1] == c and k[3] in S_set]
        rc = [k for k in x3_keys if k[1] == c and k[3] in RC_set]
        dx = [k for k in x3_keys if k[1] == c and k[3] in D_set]
        hyd = [k for k in x3_keys if k[1] == c and k[3] in HYD_set]
        pyr = [k for k in x3_keys if k[1] == c and k[3] in PYR_set]
        if hv:
            model.addCons(quicksum(x3[k] for k in hv) >= float(p["min_high_value_share"]) * total_c,
                          name="hv_" + c)
        if sl:
            model.addCons(quicksum(x3[k] for k in sl) >= float(p["min_second_life_share"]) * total_c,
                          name="sl_" + c)
        if rc:
            model.addCons(quicksum(x3[k] for k in rc) >= float(p["min_recycle_share"]) * total_c,
                          name="rc_" + c)
        if dx:
            model.addCons(quicksum(x3[k] for k in dx) <= float(p["max_disposal_share"]) * total_c,
                          name="dx_" + c)
        if rc:
            model.addCons(quicksum(x3[k] for k in hyd) >= float(p["min_hydromet_share_of_recycling"]) * quicksum(x3[k] for k in rc),
                          name="hyd_" + c)
            model.addCons(quicksum(x3[k] for k in pyr) <= float(p["max_pyromet_share_of_recycling"]) * quicksum(x3[k] for k in rc),
                          name="pyr_" + c)

    # Carbon cap
    em_terms = []
    for h in H:
        em_terms.append(feH[h] * y[h])
    for t in T:
        em_terms.append(feT[t] * z[t])
    for k in x1_keys:
        m, c, h = k
        L = lane1[(m, h)]
        em_terms.append((L["dist"] * L["epk"] + heH[h]) * x1[k])
    for k in x2_keys:
        m, c, h, t = k
        L = lane2[(h, t)]
        em_terms.append((L["dist"] * L["epk"] + teT[t]) * x2[k])
    for k in x3_keys:
        m, c, t, o = k
        L = lane3[(t, o)]
        em_terms.append((L["dist"] * L["epk"] + peO[(o, c)]) * x3[k])
    model.addCons(quicksum(em_terms) <= carbon_cap, name="carbon")

    model.setMinimize()

    tlimit = 300.0
    env = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
    if env:
        try:
            tlimit = min(tlimit, float(env))
        except ValueError:
            pass
    model.setParam("limits/gap", 0.0005)
    model.setParam("limits/time", tlimit)

    model.optimize()

    status = model.getStatus()
    nsols = model.getNSols()
    print("status:", status)
    print("nsols:", nsols)
    if nsols == 0:
        raise SystemExit("No solution found; status=%s" % status)
    obj = model.getObjVal(original=True)
    print("objective:", obj)

    # Extract solution
    rows = []
    for h in H:
        if round(model.getVal(y[h])) == 1:
            rows.append(["open", "collection_hub", h, "", "", "", "1"])
    for t in T:
        if round(model.getVal(z[t])) == 1:
            rows.append(["open", "testing_center", t, "", "", "", "1"])

    def fmt(v):
        v = float(v)
        if abs(v) < 1e-9:
            return "0"
        s = "%.8f" % v
        s = s.rstrip("0").rstrip(".")
        return s if s else "0"

    for k in x1_keys:
        m, c, h = k
        v = model.getVal(x1[k])
        if v > 1e-9:
            rows.append(["flow", "market_to_hub", m, h, m, c, fmt(v)])
    for k in x2_keys:
        m, c, h, t = k
        v = model.getVal(x2[k])
        if v > 1e-9:
            rows.append(["flow", "hub_to_test", h, t, m, c, fmt(v)])
    for k in x3_keys:
        m, c, t, o = k
        v = model.getVal(x3[k])
        if v > 1e-9:
            rows.append(["flow", "test_to_outlet", t, o, m, c, fmt(v)])

    os.makedirs("/app/submissions", exist_ok=True)
    with open(OUT, "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["record_type", "stage", "origin_id", "destination_id", "market_id", "chemistry", "quantity"])
        for r in rows:
            w.writerow(r)
    print("wrote", OUT, "rows:", len(rows))

    # ---- Validation ----
    ok = True
    def check(cond, msg):
        nonlocal ok
        if not cond:
            ok = False
            print("VIOLATION:", msg)

    # Rebuild solution dicts from rows
    # For market_to_hub: row = ["flow","market_to_hub", origin=market, dest=hub, market_id, chemistry, qty]
    # For hub_to_test:   row = ["flow","hub_to_test", origin=hub, dest=test, market_id, chemistry, qty]
    # For test_to_outlet:row = ["flow","test_to_outlet", origin=test, dest=outlet, market_id, chemistry, qty]
    f1 = {}  # (m, c, h) -> qty
    f2 = {}  # (m, c, h, t) -> qty
    f3 = {}  # (m, c, t, o) -> qty
    opened_h = set()
    opened_t = set()
    for r in rows:
        if r[0] == "open":
            if r[1] == "collection_hub":
                opened_h.add(r[2])
            else:
                opened_t.add(r[2])
        else:
            v = float(r[6])
            stage = r[1]
            origin = r[2]
            dest = r[3]
            mid = r[4]
            chem = r[5]
            if stage == "market_to_hub":
                # origin=market, dest=hub
                key = (mid, chem, dest)
                f1[key] = f1.get(key, 0.0) + v
            elif stage == "hub_to_test":
                # origin=hub, dest=test
                key = (mid, chem, origin, dest)
                f2[key] = f2.get(key, 0.0) + v
            elif stage == "test_to_outlet":
                # origin=test, dest=outlet
                key = (mid, chem, origin, dest)
                f3[key] = f3.get(key, 0.0) + v

    # Supply
    for m in M:
        for c in C:
            s = sum(v for (mm, cc, h), v in f1.items() if mm == m and cc == c)
            check(abs(s - V[(m, c)]) <= tol * max(1.0, V[(m, c)]),
                  "supply %s %s: %f vs %f" % (m, c, s, V[(m, c)]))

    # Hub conservation and eligibility
    for (m, c, h), v in f1.items():
        s = sum(v2 for (mm, cc, hh, t), v2 in f2.items() if mm == m and cc == c and hh == h)
        check(abs(s - v) <= tol * max(1.0, v), "hub cons %s %s %s: in %f out %f" % (m, c, h, v, s))
        check(h in opened_h, "hub not opened %s" % h)
        L = lane1.get((m, h))
        check(L is not None and L[c] == 1, "lane1 eligibility %s %s %s" % (m, c, h))

    # Test conservation and eligibility
    for (m, c, h, t), v in f2.items():
        s = sum(v2 for (mm, cc, tt, o), v2 in f3.items() if mm == m and cc == c and tt == t)
        check(abs(s - v) <= tol * max(1.0, v), "test cons %s %s %s %s: in %f out %f" % (m, c, h, t, v, s))
        check(t in opened_t, "test not opened %s" % t)
        L = lane2.get((h, t))
        check(L is not None and L[c] == 1, "lane2 eligibility %s %s %s %s" % (m, c, h, t))
        if c == "nmc":
            check(nmcH[h] == 1, "NMC hub cert %s" % h)

    # Outlet eligibility
    for (m, c, t, o), v in f3.items():
        check(elO[(o, c)] == 1, "outlet chem %s %s" % (o, c))
        L = lane3.get((t, o))
        check(L is not None and L[c] == 1, "lane3 eligibility %s %s %s %s" % (m, c, t, o))
        if o in R_set:
            check(rcT[t] == 1, "reman cert %s" % t)
            if Trace[m] < 0.75:
                check(auT[t] == 1, "traceability reman %s %s" % (m, t))

    # Facility capacity / min throughput
    for h in H:
        s = sum(v for (m, c, hh), v in f1.items() if hh == h)
        if h in opened_h:
            check(s <= capH[h] + tol, "hub cap %s: %f" % (h, s))
            check(s >= minH[h] - tol, "hub min %s: %f" % (h, s))
        else:
            check(s <= tol, "hub closed flow %s: %f" % (h, s))
    for t in T:
        s = sum(v for (m, c, hh, tt), v in f2.items() if tt == t)
        if t in opened_t:
            check(s <= capT[t] + tol, "test cap %s: %f" % (t, s))
            check(s >= minT[t] - tol, "test min %s: %f" % (t, s))
        else:
            check(s <= tol, "test closed flow %s: %f" % (t, s))

    # Outlet capacity
    for o in O:
        s = sum(v for (m, c, t, oo), v in f3.items() if oo == o)
        check(s <= capO[o] + tol, "outlet cap %s: %f" % (o, s))

    # Lane capacity
    for (m, h), L in lane1.items():
        s = sum(v for (mm, c, hh), v in f1.items() if mm == m and hh == h)
        check(s <= L["cap"] + tol, "lane1 cap %s %s: %f" % (m, h, s))
    for (h, t), L in lane2.items():
        s = sum(v for (m, c, hh, tt), v in f2.items() if hh == h and tt == t)
        check(s <= L["cap"] + tol, "lane2 cap %s %s: %f" % (h, t, s))
    for (t, o), L in lane3.items():
        s = sum(v for (m, c, tt, oo), v in f3.items() if tt == t and oo == o)
        check(s <= L["cap"] + tol, "lane3 cap %s %s: %f" % (t, o, s))

    # Audited share
    for m in M:
        total = sum(V[(m, c)] for c in C)
        aud = sum(v for (mm, c, h, t), v in f2.items() if mm == m and auT[t] == 1)
        check(aud >= AudReq[m] * total - tol, "audit share %s: %f vs %f" % (m, aud, AudReq[m] * total))

    # Damaged cap
    for m in M:
        for c in C:
            hv = sum(v for (mm, cc, t, o), v in f3.items() if mm == m and cc == c and o in HV_set)
            check(hv <= (1.0 - Dmg[(m, c)]) * V[(m, c)] + tol, "dmg cap %s %s: %f" % (m, c, hv))

    # Policy rules
    for c in C:
        total_c = sum(V[(m, c)] for m in M)
        p = pol[c]
        hv = sum(v for (m, cc, t, o), v in f3.items() if cc == c and o in HV_set)
        sl = sum(v for (m, cc, t, o), v in f3.items() if cc == c and o in S_set)
        rc = sum(v for (m, cc, t, o), v in f3.items() if cc == c and o in RC_set)
        dx = sum(v for (m, cc, t, o), v in f3.items() if cc == c and o in D_set)
        hyd = sum(v for (m, cc, t, o), v in f3.items() if cc == c and o in HYD_set)
        pyr = sum(v for (m, cc, t, o), v in f3.items() if cc == c and o in PYR_set)
        check(hv >= float(p["min_high_value_share"]) * total_c - tol, "hv %s: %f" % (c, hv))
        check(sl >= float(p["min_second_life_share"]) * total_c - tol, "sl %s: %f" % (c, sl))
        check(rc >= float(p["min_recycle_share"]) * total_c - tol, "rc %s: %f" % (c, rc))
        check(dx <= float(p["max_disposal_share"]) * total_c + tol, "dx %s: %f" % (c, dx))
        if rc > tol:
            check(hyd >= float(p["min_hydromet_share_of_recycling"]) * rc - tol,
                  "hyd %s: %f vs %f" % (c, hyd, float(p["min_hydromet_share_of_recycling"]) * rc))
            check(pyr <= float(p["max_pyromet_share_of_recycling"]) * rc + tol,
                  "pyr %s: %f vs %f" % (c, pyr, float(p["max_pyromet_share_of_recycling"]) * rc))

    # Carbon cap
    em = 0.0
    for h in opened_h:
        em += feH[h]
    for t in opened_t:
        em += feT[t]
    for (m, c, h), v in f1.items():
        L = lane1[(m, h)]
        em += (L["dist"] * L["epk"] + heH[h]) * v
    for (m, c, h, t), v in f2.items():
        L = lane2[(h, t)]
        em += (L["dist"] * L["epk"] + teT[t]) * v
    for (m, c, t, o), v in f3.items():
        L = lane3[(t, o)]
        em += (L["dist"] * L["epk"] + peO[(o, c)]) * v
    check(em <= carbon_cap + tol, "carbon cap: %f vs %f" % (em, carbon_cap))
    print("emissions:", em)

    # Schema check
    stages = {"market_to_hub", "hub_to_test", "test_to_outlet"}
    for r in rows:
        if r[0] == "open":
            check(r[1] in ("collection_hub", "testing_center") and r[6] == "1", "open schema")
        else:
            check(r[1] in stages and r[5] in C and r[4] in M, "flow schema")
    print("VALIDATION", "PASSED" if ok else "FAILED")

    model.free()


